interface Fruit {
    public String name();
}

class Broccoli {
   public String name() {
       return "Broccoli hehe";
   }

}




{{ STUDENT_ANSWER }}

class Test {
  public static void adapterPatternUsed() {
       Fruit broccoli = new BroccoliAdapter();
       if(broccoli.name().equals("Broccoli hehe")) {
          System.out.println("true");
       }
       else System.out.println("false");
  }

  public static void canConstruct() {
      Fruit broccoli;
      try {
        broccoli = new BroccoliAdapter();
      }
      catch(Exception e) {
          System.out.println("false");
          return;
      }
      System.out.println("true");
  }
}

