class Test {
  public static void cannotMakeSecondInstance() {
    try {
      ChocolateBoiler boiler1 = ChocolateBoiler.getBoiler();
      ChocolateBoiler boiler2 = ChocolateBoiler.getBoiler();
      if(boiler1.equals(boiler2)) {
          System.out.println("true");
      } else {
          System.out.println("false");
      }
    } catch (java.lang.NullPointerException e) { System.out.println("false"); }
  }

  public static void cannotConstruct() {
    Constructor[] constructors = ChocolateBoiler.class.getDeclaredConstructors();
    for(int i=0; i<constructors.length; i++) {
      if(Modifier.isPublic(constructors[i].getModifiers())) {
        System.out.println("false");
        return;
      }
    }
    System.out.println("true");
  }
}

