question.template:
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;

public class prog {
    public static void main(String[] args) {
        SomeBigComputation.main(new String[]{});
        while(Thread.activeCount() > 1) {
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {}
        }
        {{ TEST.testcode }}
    }
}

class SomeBigComputation {
  public static final int NUM_THREADS = 16;
  public static final int PROBLEM_SIZE = 10000000;
  public static int SUBPROBLEM_SIZE;

  public static void someBigComputation(int start, int end) {
    CallLog.addStaticCall(new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingMethod()
      .getName(),
    new Object[] { start, end },
    null);
  }
  {{ STUDENT_ANSWER }}
}

class Test {
    // public static void correct_SUBPROBLEM_SIZE() {
    //     System.out.println(SomeBigComputation.SUBPROBLEM_SIZE == SomeBigComputation.PROBLEM_SIZE / (SomeBigComputation.NUM_THREADS + 1));
    // }

    public static void correct_SUBPROBLEM_SIZE() {
        boolean passed = true;
        int NUM_THREADS = SomeBigComputation.NUM_THREADS;
        int SUBPROBLEM_SIZE = SomeBigComputation.SUBPROBLEM_SIZE;
        int PROBLEM_SIZE = SomeBigComputation.PROBLEM_SIZE;
        double threads_required = (double) PROBLEM_SIZE / (double) SUBPROBLEM_SIZE;
        if(threads_required > (double) NUM_THREADS) {
              passed = false;
        }
        if(threads_required < (double) (NUM_THREADS - 1)) {
              passed = false;
        }
        if(SUBPROBLEM_SIZE == PROBLEM_SIZE / (NUM_THREADS + 1)) {
            passed = true;
        }
        System.out.println(passed);
    }

    public static void not_running_on_main_thread() {
        boolean passed = true;
        for(Call c: CallLog._calls) {
            if(c.method.equals("someBigComputation") && c.threadID == CallLog._mainThreadId) {
              passed = false;
            }
        }
        System.out.println(passed);
    }

    public static void created_NUM_THREADS_threads() {
        boolean passed = true;
        java.util.Set<Long> threads = new java.util.HashSet<Long>();
        for(Call c: CallLog._calls) {
            if(c.method.equals("someBigComputation")) {
                threads.add(c.threadID);
            }
        }
        if(threads.size() < SomeBigComputation.NUM_THREADS) {
            passed = false;
        }
        System.out.println(passed);
    }

    public static void correct_initialisation_of_CountDownLatch() {
        boolean passed = true;
        for(Call c: CallLog._calls) {
            if(c.className.equals("CountDownLatch")) {
                if(c.isConstructor) {
                    if(c.args.length == 1) {
                        if((int) c.args[0] != 1) {
                            passed = false;
                        }
                    }
                }
            }
        }
        System.out.println(passed);
    }

    public static void correct_order_of_operations(){
        boolean passed = false;
        long latchCreate = 0;
        long firstAwait = 0;
        long lastAwait = 0;
        long latchCountDown = 0;
        long firstSBC = 0;
        for(Call c: CallLog._calls) {
            if(c.className.equals("CountDownLatch") && c.isConstructor) {
                latchCreate = c.time;
            }
            if(c.method.equals("await")) {
                if(firstAwait == 0) {
                    firstAwait = c.time;
                } else {
                    lastAwait = c.time;
                }
            }
            if(c.method.equals("countDown")) {
                latchCountDown = c.time;
            }
            if(c.method.equals("someBigComputation") && firstSBC == 0) {
                firstSBC = c.time;
            }
        }
        if(latchCreate < firstAwait && lastAwait < latchCountDown && latchCountDown < firstSBC) {
            passed = true;
        }
        System.out.println(passed);
    }
}

class CountDownLatch extends java.util.concurrent.CountDownLatch {
  public CountDownLatch(int count) {
    super(count);
    CallLog.addInstance(this);
    CallLog.addCall(this,
    true,
    new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingConstructor()
      .getName(),
      new Object[] { count },
      null);
  }

  @Override
  public void await() throws InterruptedException {
    CallLog.addCall(this,
    false,
    new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingMethod()
      .getName(),
      new Object[] {},
      null);
    super.await();
  }

  @Override
  public void countDown() {
    CallLog.addCall(this,
    false,
    new Object() {}
      .getClass()
      .getEnclosingClass()
      .getName(),
    new Object() {}
      .getClass()
      .getEnclosingMethod()
      .getName(),
      new Object[] {},
      null);
    super.countDown();
  }
}

class CallLog {
  static long _mainThreadId = Thread.currentThread().getId();
  static java.util.concurrent.atomic.AtomicInteger _varname = new java.util.concurrent.atomic.AtomicInteger(1);
  static java.util.concurrent.ConcurrentHashMap<Object,Integer> _instances = new java.util.concurrent.ConcurrentHashMap<Object,Integer>(); 
  static java.util.concurrent.CopyOnWriteArrayList<Call> _calls = new java.util.concurrent.CopyOnWriteArrayList<Call>();

  static void addInstance(Object obj) {
    _instances.put(obj, _varname.getAndIncrement());
  }

  static void addCall(Object obj, Boolean isConstructor, String className, String method, Object[] args, Object result) {
    _calls.add(new Call(_instances.get(obj), isConstructor, className, method, args, result));
  }

  static void addStaticCall(String className, String method, Object[] args, Object result) {
    _calls.add(new Call(0, false, className, method, args, result));
  }

  static void dump() {
    for(Call c: _calls) {
      System.err.println(c);
    }
  }
}

class Call {
  long time;
  long threadID;
  Integer target;
  boolean isConstructor;
  String className;
  String method;
  Object[] args;
  Object result;

  public Call(Integer target, boolean isConstructor, String className, String method, Object[] args, Object result) {
    this.time = System.nanoTime();
    this.threadID = Thread.currentThread().getId();
    this.target = target;
    this.isConstructor = isConstructor;
    this.className = className;
    this.method = method;
    this.args = args;
    this.result = result;
  }

  public String toString() {
    StringBuilder s = new StringBuilder();
    s.append(Long.toString(time) + ",");
    if(isConstructor && method != null) {
        s.append(method.toString() + " ");
    }
    if(target != null) {
      s.append(className.toLowerCase() + target.toString());
    }
    if(isConstructor) {
      if(method != null) {
        s.append(" = new " + method.toString());
      }
    } else {
      if(method != null) {
        s.append("." + method.toString());
      }
    }
    if(args != null) {
      s.append("(");
      for(int i=0; i < args.length; i++) {
        s.append(args[i].toString());
        if(i < args.length-1) {
          s.append(",");
        }
      }
      s.append(")");
    }
    if(result != null) {
      s.append(" -> " + result.toString());
    }
    s.append(";");
    return s.toString();
  }
}

question.answer:
public static void main(String[] args) {
    ThreadPoolExecutor pool = (ThreadPoolExecutor) Executors.newFixedThreadPool(NUM_THREADS);
    CountDownLatch starter = new CountDownLatch(1);

    SUBPROBLEM_SIZE = PROBLEM_SIZE / NUM_THREADS + 1;
    for (int i = 0; i < NUM_THREADS; i++) {
      int rangeStart = i * SUBPROBLEM_SIZE;
      int rangeEnd = Math.min(PROBLEM_SIZE, rangeStart + SUBPROBLEM_SIZE);

      pool.execute(() -> {
        try {
          starter.await();
        } catch (InterruptedException e) {}
        someBigComputation(rangeStart, rangeEnd);
      });
    }
    starter.countDown();
    pool.shutdown();
}

